package kr.workbench;
import burp.api.montoya.*;import burp.api.montoya.http.*;import burp.api.montoya.http.message.*;import burp.api.montoya.http.message.requests.*;import burp.api.montoya.http.message.params.*;import burp.api.montoya.http.handler.*;import burp.api.montoya.scope.*;import burp.api.montoya.internal.*;
import javax.swing.*;import javax.swing.table.*;import java.nio.file.*;import java.util.*;import java.util.List;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.zip.*;
public final class ActivityReconTest extends WorkbenchTest {
 static HttpRequest withParams(String url,String method,String... pairs){List<ParsedHttpParameter> params=new ArrayList<>();for(int i=0;i<pairs.length;i+=3){String type=pairs[i],name=pairs[i+1],value=pairs[i+2];params.add(proxy(ParsedHttpParameter.class,(p,m,a)->switch(m.getName()){case "type"->HttpParameterType.valueOf(type);case "name"->name;case "value"->value;default->def(m);}));}HttpRequest base=request(url,method,true,List.of());return proxy(HttpRequest.class,(p,m,a)->m.getName().equals("parameters")?params:m.invoke(base,a));}
 static ActivityTracker.View view(ActivityTracker t,String method,String suffix){return t.views().stream().filter(v->v.method().equals(method)&&v.url().endsWith(suffix)).findFirst().orElseThrow();}
 static void idle(ActivityPanel p)throws Exception {CountDownLatch latch=new CountDownLatch(1);p.submit(latch::countDown);check(latch.await(10,TimeUnit.SECONDS),"activity queue drained");edt(p::refresh);}
 public static void main(String[] args)throws Exception {
  ActivityTracker t=new ActivityTracker();t.observe(withParams("https://example.test/api?id=123","GET","URL","id","123","BODY","name","alice","COOKIE","sid","hidden"),"PROXY");var v=view(t,"GET","/api");check(v.state().equals("요청 관측")&&v.url().equals("https://example.test/api"),"proxy observation is not completion and values omitted from URL");check(v.parameters().size()==3,"URL body and cookie parameter locations tracked");
  t.observe(withParams("https://example.test/api?id=123","GET","URL","id","123","BODY","name","alice","COOKIE","sid","hidden"),"REPEATER");check(view(t,"GET","/api").repeater()==1&&!view(t,"GET","/api").state().equals("점검 완료"),"actual Repeater send records work, not completion");check(view(t,"GET","/api").parameters().stream().noneMatch(p->p.state().equals("변경 관찰")),"unchanged replay does not claim changed parameters");
  t.observe(withParams("https://example.test/api?id=456","GET","URL","id","456","BODY","name","bob"),"REPEATER");check(view(t,"GET","/api").parameters().stream().allMatch(p->p.state().equals("변경 관찰")),"changed URL body values and removed cookie are observed");
  t.observe(request("http://example.test/api?id=456","GET",true,List.of()),"PROXY");t.observe(request("https://example.test:8443/api?id=456","GET",true,List.of()),"PROXY");t.observe(request("https://example.test/api","POST",true,List.of()),"PROXY");check(t.views().size()==4,"scheme port and method isolate endpoint identities");check(ActivityTracker.safeUrl("https://EXAMPLE.test:443/api?q=x#f").equals("https://example.test/api"),"default port host and fragments canonicalized");check(ActivityTracker.safeUrl("https://user:pass@example.test/a")==null,"credential-bearing URLs excluded");
  String key=view(t,"GET","/api").key();t.complete(key,true);t.completeParameter(key,"URL:id",true);check(view(t,"GET","/api").state().equals("점검 완료"),"explicit endpoint completion works");check(view(t,"GET","/api").parameters().stream().anyMatch(p->p.key().equals("URL:id")&&p.state().equals("점검 완료")),"parameter completion independent of endpoint");t.complete(key,false);check(!view(t,"GET","/api").state().equals("점검 완료"),"completion can be reopened");
  t.discover("https://example.test/api?new=secret","Wayback");check(t.views().size()==4,"unknown-method discovery joins known endpoint");t.discover("https://example.test/missing?token=SECRET_VALUE","JS");check(view(t,"?","/missing").state().equals("발견만 함"),"unvisited JS endpoint retained as gap");t.observe(request("https://example.test/missing?token=new","GET",true,List.of()),"PROXY");check(t.views().stream().noneMatch(e->e.method().equals("?")),"observed method reconciles unknown discovery");
  String saved=t.save();check(!saved.contains("SECRET_VALUE")&&!saved.contains("alice")&&!saved.contains("baseline"),"saved state contains neither parameter values nor hashes");ActivityTracker restored=new ActivityTracker();restored.load(saved);check(restored.views().equals(t.views()),"metadata round trip restores counters and explicit status");String before=restored.save();try{restored.load("{bad}");throw new AssertionError();}catch(IllegalArgumentException ex){check(restored.save().equals(before),"invalid imports preserve current record");}
  ActivityTracker duplicates=new ActivityTracker();duplicates.observe(request("https://example.test/d?a=1&a=2","GET",true,List.of()),"PROXY");duplicates.observe(request("https://example.test/d?a=1&a=3","GET",true,List.of()),"REPEATER");check(duplicates.views().get(0).parameters().get(0).state().equals("변경 관찰"),"duplicate parameter value changes detected");
  check(ReconMetadata.category("https://example.test/admin/users").equals("관리자/내부"),"admin classification");check(ReconMetadata.category("https://example.test/payment").equals("자금/결제"),"money classification");check(ReconMetadata.category("https://example.test/oauth/token").equals("인증"),"auth classification");check(ReconMetadata.category("https://example.test/upload").equals("파일 처리"),"file classification");check(ReconMetadata.category("https://example.test/item?id=1").equals("객체 접근"),"object classification");check(ReconMetadata.pattern("https://example.test/users/123?id=secret").equals(ReconMetadata.pattern("https://example.test/users/456?id=other")),"dynamic IDs and query values grouped");check(!ReconMetadata.pattern("https://example.test/api/user").equals(ReconMetadata.pattern("https://example.test/api/admin")),"distinct static paths never discarded");check(ReconMetadata.risk("https://example.test/.git/config").equals("민감 파일 후보"),"sensitive file candidate");check(ReconMetadata.risk("https://example.test/a?token=x").equals("인증정보 파라미터"),"credential parameter candidate does not expose value");check(ReconMetadata.dangerous("https://example.test/user/delete")&&ReconMetadata.dangerous("https://example.test/%64elete/123"),"encoded destructive paths identified");check(!ReconMetadata.dangerous("https://example.test/deleted-items"),"unrelated similar words do not block verification");
  var found=ReconMetadata.discover("https://example.test/assets/app.js","fetch('/hidden?id=123',{method:'POST',body:{name:'x'}});",true);check(found.stream().anyMatch(d->d.url().equals("https://example.test/hidden")&&d.query().contains("id")&&d.body().contains("name")&&d.method().equals("POST")),"JS API method query names body names extracted offline");var forms=ReconMetadata.discover("https://example.test/page","<a href='/next?a=1&amp;b=2'>x</a><form action='/submit' method='post'><input name='email'></form>",false);check(forms.stream().anyMatch(d->d.url().contains("/next?a=1&b=2")),"HTML entities resolved");check(forms.stream().anyMatch(d->d.method().equals("POST")&&d.body().contains("email")),"HTML form fields become parameter gaps");
  AtomicInteger sent=new AtomicInteger();var http=proxy(Http.class,(p,m,a)->{if(m.getName().equals("sendRequest")){sent.incrementAndGet();HttpRequest q=(HttpRequest)a[0];return proxy(HttpRequestResponse.class,(pp,mm,aa)->switch(mm.getName()){case "request"->q;case "response"->response(q.url().contains("rate")?429:200,"{}");default->def(mm);});}return def(m);});var scopeApi=proxy(Scope.class,(p,m,a)->m.getName().equals("isInScope")&&!((String)a[0]).contains("outside"));MontoyaApi api=proxy(MontoyaApi.class,(p,m,a)->switch(m.getName()){case "http"->http;case "scope"->scopeApi;default->def(m);});
  ObjectFactoryLocator.FACTORY=proxy(MontoyaObjectFactory.class,(p,m,a)->switch(m.getName()){case "httpRequestFromUrl"->request((String)a[0],"GET",!((String)a[0]).contains("outside"),List.of());case "requestOptions"->proxy(RequestOptions.class,(pp,mm,aa)->pp);default->def(m);});
  AtomicReference<ActivityPanel> box=new AtomicReference<>();edt(()->box.set(new ActivityPanel(api)));ActivityPanel panel=box.get();panel.observe(request("https://example.test/a?key=one","GET",true,List.of()),"PROXY");panel.discover("https://outside.test/missing","JS");panel.response(request("https://example.test/app.js","GET",true,List.of()),response(200,"fetch('/js-gap?token=abc');fetch('https://outside.test/api');"));idle(panel);check(panel.tracker.views().size()==2,"Scope filtering applies to passive and JS discovery");check(sent.get()==0,"coverage collection and analysis send no target traffic");edt(()->{panel.table.setRowSelectionInterval(0,0);panel.search.setText("js-gap");check(panel.table.getRowCount()==1&&panel.parameterTable.getRowCount()==0,"filtered selection clears stale parameter details");panel.search.setText("");panel.table.setRowSelectionInterval(0,0);});panel.observe(request("https://example.test/a?key=two","GET",true,List.of()),"REPEATER");idle(panel);check(panel.tracker.views().stream().anyMatch(e->e.repeater()==1),"background activity continues independent of traffic rows");
  AtomicReference<PassiveScanPanel> pb=new AtomicReference<>();edt(()->{pb.set(new PassiveScanPanel(api));pb.get().target.setText("example.test");pb.get().importUrls("https://example.test/users/123?id=1\nhttps://example.test/users/456?id=2\nhttps://example.test/a.png\nhttps://example.test/admin\nhttps://outside.test/no\n");});PassiveScanPanel passive=pb.get();check(passive.items.size()==4,"passive import filters unrelated domains");edt(()->{passive.hideStatic.doClick();check(passive.table.getRowCount()==3,"static filter preserves hidden records");passive.category.setSelectedItem("관리자/내부");check(passive.visible().equals(List.of("https://example.test/admin")),"category filter controls verification selection");passive.category.setSelectedItem("전체");passive.importPrevious("https://example.test/admin\nhttps://example.test/old\n");check(passive.items.size()==5&&passive.previous.size()==2,"previous database merges and marks old URLs");passive.importUrls("https://example.test/delete/123\n");passive.verify(List.of("https://example.test/delete/123"));check(passive.job==null,"destructive GET path excluded before sending");});check(sent.get()==0,"excluded verification sends zero requests");
  edt(()->{passive.importUrls("https://example.test/rate\nhttps://example.test/later\n");passive.verify(List.of("https://example.test/rate","https://example.test/later"));});PassiveScanTest.idle(passive);check(sent.get()==1&&passive.items.get("https://example.test/rate").state.equals("HTTP 429"),"rate limit stops remaining requests and retains packet");
  Path excel=Files.createTempFile(Path.of("build"),"coverage-", ".xlsx");var sheets=ActivityTracker.workbook(t.views());sheets.put("수식 테스트",List.of(List.of("=HYPERLINK(\"bad\")","한글 & <텍스트>")));MetadataExport.xlsx(excel,sheets);try(ZipFile zip=new ZipFile(excel.toFile())){String xml=new String(zip.getInputStream(zip.getEntry("xl/worksheets/sheet4.xml")).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);check(xml.contains("inlineStr")&&!xml.contains("<f>")&&xml.contains("&lt;텍스트&gt;"),"Excel strings prevent formula execution and preserve Korean XML");}Path sample=Path.of("build/activity-coverage-sample.xlsx");MetadataExport.xlsx(sample,sheets);Files.delete(excel);
  ActivityTracker bounded=new ActivityTracker();for(int i=0;i<ActivityTracker.LIMIT+1;i++)bounded.discover("https://example.test/"+i,"fixture");check(bounded.views().size()==ActivityTracker.LIMIT&&bounded.rejected==1,"coverage endpoint cap explicit and bounded");ActivityTracker large=new ActivityTracker();large.load(bounded.save());check(large.views().size()==ActivityTracker.LIMIT,"large bounded records can be reloaded");
  edt(()->{panel.close();passive.close();});panel.observe(request("https://example.test/after","GET",true,List.of()),"REPEATER");check(panel.tracker.views().isEmpty()&&panel.worker.isShutdown(),"unload clears metadata and stops workers");System.out.println("ActivityReconTest: "+checks+" checks passed");
 }
}
